import [printf] from "std/c.bpl";

frame main() ret int {
    local x: int = 42;

    # Create a pointer using & (address-of operator)
    local ptr: *int = &x;

    printf("x = %d\n", x);
    printf("Address of x: %p\n", ptr);

    # Dereference pointer using * to get the value
    printf("Value at ptr (*ptr): %d\n", *ptr);

    # Modify the value through the pointer
    *ptr = 100;
    printf("\nAfter *ptr = 100:\n");
    printf("x = %d\n", x);        # x is now 100!
    printf("*ptr = %d\n", *ptr);  # Same value

    # Change x and see it through pointer
    x = 999;
    printf("\nAfter x = 999:\n");
    printf("*ptr = %d\n", *ptr);  # Pointer sees the change

    return 0;
}

import [printf] from "std/c.bpl";

# Without pointer: can't modify original
frame tryToDouble(n: int) {
    n = n * 2;  # Only modifies local copy!
    printf("Inside tryToDouble: %d\n", n);
}

# With pointer: can modify original
frame actuallyDouble(n: *int) {
    *n = *n * 2;  # Modifies the original!
    printf("Inside actuallyDouble: %d\n", *n);
}

frame main() ret int {
    local value: int = 10;
    printf("Original value: %d\n", value);

    # Try to double without pointer
    printf("\nCalling tryToDouble...\n");
    tryToDouble(value);
    printf("After tryToDouble: %d\n", value);  # Still 10!

    # Double with pointer
    printf("\nCalling actuallyDouble...\n");
    actuallyDouble(&value);
    printf("After actuallyDouble: %d\n", value);  # Now 20!

    return 0;
}

import [printf] from "std/c.bpl";

# Classic swap function - needs pointers!
frame swap(a: *int, b: *int) {
    local temp: int = *a;
    *a = *b;
    *b = temp;
}

frame main() ret int {
    local x: int = 10;
    local y: int = 20;

    printf("Before swap: x=%d, y=%d\n", x, y);

    swap(&x, &y);

    printf("After swap: x=%d, y=%d\n", x, y);

    # Swap them back
    swap(&x, &y);
    printf("After second swap: x=%d, y=%d\n", x, y);

    return 0;
}

import [printf] from "std/c.bpl";

struct Point {
    x: int,
    y: int,
}

frame movePoint(p: *Point, dx: int, dy: int) {
    # Access struct fields through pointer
    p.x = p.x + dx;  # BPL auto-dereferences for field access
    p.y = p.y + dy;
}

frame printPoint(p: *Point) {
    printf("Point(%d, %d)\n", p.x, p.y);
}

frame main() ret int {
    local point: Point = Point { x: 0, y: 0 };

    printf("Initial: ");
    printPoint(&point);

    movePoint(&point, 5, 10);
    printf("After move(5, 10): ");
    printPoint(&point);

    movePoint(&point, -3, 7);
    printf("After move(-3, 7): ");
    printPoint(&point);

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    local data: int = 100;

    # Multiple pointers to the same location
    local p1: *int = &data;
    local p2: *int = &data;
    local p3: *int = p1;  # Copy the pointer value

    printf("data = %d\n", data);
    printf("*p1 = %d\n", *p1);
    printf("*p2 = %d\n", *p2);
    printf("*p3 = %d\n", *p3);

    # Modify through one pointer
    *p1 = 200;

    printf("\nAfter *p1 = 200:\n");
    printf("data = %d\n", data);
    printf("*p2 = %d\n", *p2);  # Sees the change!
    printf("*p3 = %d\n", *p3);  # Sees the change!

    return 0;
}

import [printf] from "std/c.bpl";

# Safe function that checks for null
frame safePrint(ptr: *int) {
    if (ptr == nullptr) {
        printf("Error: null pointer!\n");
        return;
    }
    printf("Value: %d\n", *ptr);
}

# Function that returns success/failure
frame safeIncrement(ptr: *int) ret bool {
    if (ptr == nullptr) {
        return false;
    }
    *ptr = *ptr + 1;
    return true;
}

frame main() ret int {
    local value: int = 42;
    local valid: *int = &value;
    local invalid: *int = nullptr;

    printf("Valid pointer:\n");
    safePrint(valid);

    printf("\nNull pointer:\n");
    safePrint(invalid);

    printf("\nIncrement valid: %d\n", safeIncrement(valid));
    safePrint(valid);

    printf("\nIncrement null: %d\n", safeIncrement(invalid));

    return 0;
}

