import [printf] from "std/c.bpl";

frame stats(arr: *int, len: int, outMin: *int, outMax: *int, outSum: *int) {
    *outMin = *arr;
    *outMax = *arr;
    *outSum = 0;

    loop (local i: int = 0; i < len; i = i + 1) {
        local val: int = *(arr + i);
        *outSum = *outSum + val;
        if (val < *outMin) { *outMin = val; }
        if (val > *outMax) { *outMax = val; }
    }
}

frame main() ret int {
    local data: int[5] = [5, 2, 8, 1, 9];
    local min: int;
    local max: int;
    local sum: int;

    stats(&data[0], 5, &min, &max, &sum);

    printf("Min: %d\n", min);
    printf("Max: %d\n", max);
    printf("Sum: %d\n", sum);
    printf("Avg: %d\n", sum / 5);

    return 0;
}
